import axios from 'axios';

// Tạo cấu hình chung cho axios
const api = axios.create({
    baseURL: 'http://localhost:5000/api/tai-khoan' // Đây là đường dẫn đến Backend của bạn
});

// 1. Hàm gọi API Đăng nhập
export const apiDangNhap = (data) => api.post('/login', data);

// 2. Hàm gọi API Đăng ký (THÊM DÒNG NÀY ĐỂ HẾT LỖI)
export const apiDangKy = (data) => api.post('/register', data);

export default api;
